ction_date'],'bag_brand_id'=>(int)$sample['bag_brand_id']],JSON_HEX_APOS|JSON_HEX_QUOT),ENT_QUOTES) ?>'>Editar</button><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>

