<script>(()=>{const form=document.querySelector('#receive-form'),dialog=document.querySelector('#receive-dialog');document.querySelectorAll('.decision-control input').forEach(i=>i.addEventListener('change',()=>{i.closest('td').querySelector('.sample-reason').classList.toggle('visible',i.value==='reject'&&i.checked)}));document.querySelector('#open-receive')?.addEventListener('click',()=>{let r=0,a=0,x=0,valid=true;document.querySelectorAll('.decision-control').forEach(c=>{const v=c.querySelector('input:checked').value;if(v==='receive')r++;else if(v==='await')a++;else{x++;const reason=c.closest('td').querySelector('.sample-reason');if(!reason.value.trim()){reason.setCustomValidity('Informe o motivo da recusa.');reason.reportValidity();valid=false}else reason.setCustomValidity('')}});if(valid&&form.reportValidity()){document.querySelector('#decision-summary').textContent=`${r} amostra(s) a receber, ${a} aguardando e ${x} a recusar.`;dialog.showModal()}});document.querySelector('#confirm-receive')?.addEventListener('click',()=>form.requestSubmit());dialog.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>dialog.close()));const ed=document.querySelector('#edit-dialog'),ef=document.querySelector('#edit-form');document.querySelectorAll('.edit-sample').forEach(b=>b.addEventListener('click',()=>{const s=JSON.parse(b.dataset.sample);ef.elements.sample_id.value=s.id;Object.keys(s).forEach(k=>{if(k!=='id'&&ef.elements[k])ef.elements[k].value=s[k]??''});ed.showModal()}));ed?.querySelectorAll('[data-close-edit]').forEach(b=>b.addEventListener('click',()=>ed.close()));})();</script>
<script>
(()=>{const expired=<?= json_encode(array_map('intval',array_column(array_filter($samples,static fn($s)=>!empty($s['is_expired'])),'id'))) ?>;expired.forEach(id=>{const input=document.querySelector(`[name="decisions[${id}][action]"][value="reject"]`);if(!input)return;const cell=input.closest('td'),row=input.closest('tr');cell.querySelectorAll('input[type="radio"]').forEach(r=>{r.checked=r.value==='reject';if(r.value!=='reject')r.disabled=true});const reason=cell.querySelector('.sample-reason');reason.value='Hemocomponente vencido';reason.readOnly=true;reason.classList.add('visible');const status=row.querySelector('td:nth-child(5)');status.insertAdjacentHTML('beforeend','<small class="cell-subtitle"><strong class="status status-rejected">VENCIDO</strong><br>Recusa obrigatória por validade.</small>');const production=row.querySelector('td:nth-child(3)');const sample=<?= json_encode(array_combine(array_map('intval',array_column($samples,'id')),array_map(static fn($s)=>['expiration_date'=>$s['expiration_date']??null,'preservative'=>$s['preservative_code']??null],$samples)),JSON_UNESCAPED_UNICODE) ?>[id];if(sample?.expiration_date){const [y,m,d]=sample.expiration_date.split('-');production.insertAdjacentHTML('beforeend',`<small class="cell-subtitle">Validade: ${d}/${m}/${y}</small>`);}})})();
</script>
